#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/commands/font_command/font_command.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RibbonFontControl's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/ribbon_font_control.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The font command whose value the fields show and commit, or null; without one the control keeps its own value.
template <typename Declaring>
struct RibbonFontControlCommandCapability {
    PropertyCell<std::shared_ptr<FontCommand>, RibbonFontControlCommandCapability<Declaring>> command{};

    static void assign(RibbonFontControlCommandCapability& capability, std::shared_ptr<FontCommand> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.command), incoming);
        if (!capability.command.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.command));
    }
};

// The value shown: the command's, or the control's own. A write sets it as the program does (the command's set_value when there is one); a value FontCommand refuses throws std::invalid_argument.
template <typename Declaring>
struct RibbonFontControlValueCapability {
    PropertyView<FontChoice, RibbonFontControlValueCapability<Declaring>> value;

    static void assign(RibbonFontControlValueCapability& capability, FontChoice incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.value), std::move(incoming));
    }

    static FontChoice read(const RibbonFontControlValueCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        FontChoice current = control.read_view(capability.value);
        return current;
    }
};

// Every RibbonFontControl capability, in the order the declaring class takes them.
template <typename Declaring>
struct RibbonFontControlCapabilities : public RibbonFontControlCommandCapability<Declaring>,
                                       public RibbonFontControlValueCapability<Declaring> {};

} // namespace gui_forms
